CREATE COLUMN TABLE "TEST_AP"."OPVL" ("Code" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(50), "ConsolNum" NVARCHAR(2) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPVL_CONSOL_NUM" ON "TEST_AP"."OPVL" ( "ConsolNum" ASC )